import{_ as t,o,c as i,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"Plan — FR 3.10.11: Update AI Credit Price (UC-138)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/09-admin-functions/3-10-11-update-ai-credit-price/plan.md","filePath":"feature/srs/09-admin-functions/3-10-11-update-ai-credit-price/plan.md"}'),a={name:"feature/srs/09-admin-functions/3-10-11-update-ai-credit-price/plan.md"};function c(r,e,d,s,l,p){return o(),i("div",null,[...e[0]||(e[0]=[n('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-10-11-update-ai-credit-price-uc-138" tabindex="-1">Plan — FR 3.10.11: Update AI Credit Price (<code>UC-138</code>) <a class="header-anchor" href="#plan-—-fr-3-10-11-update-ai-credit-price-uc-138" aria-label="Permalink to &quot;Plan — FR 3.10.11: Update AI Credit Price (`UC-138`)&quot;">​</a></h1><h2 id="_1-architectural-scope-touched-repositories" tabindex="-1">1. Architectural Scope &amp; Touched Repositories <a class="header-anchor" href="#_1-architectural-scope-touched-repositories" aria-label="Permalink to &quot;1. Architectural Scope &amp; Touched Repositories&quot;">​</a></h2><p>Implements <strong>FR 3.10.11 — Update AI Credit Price</strong> (<a href="./spec.html">spec.md</a>) for canonical roles <code>Admin</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Layer / Repository</th><th style="text-align:left;">Concrete Classes &amp; Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway (<code>brandhub-api-gateway</code>)</strong></td><td style="text-align:left;"><code>InboundSecurityWebFilter.java</code>, <code>JwtAuthFilterGatewayFilterFactory.java</code>, <code>RateLimitGatewayFilterFactory.java</code></td></tr><tr><td style="text-align:left;"><strong>Business Service (<code>brandhub-business-service</code>)</strong></td><td style="text-align:left;"><code>CreditPriceController.updatePrice()</code></td></tr><tr><td style="text-align:left;"><strong>Database &amp; Persistence Layer</strong></td><td style="text-align:left;">PostgreSQL <code>ai_credit_operation_prices</code>, <code>audit_logs</code></td></tr><tr><td style="text-align:left;"><strong>Web Application (<code>brandhub-web</code>)</strong></td><td style="text-align:left;"><code>pages/credit/prices.tsx</code>, <code>pages/credit/components/CreditPriceDrawer.tsx</code>, <code>CreditAmountForm.tsx</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App (<code>brandhub-mobile-app</code>)</strong></td><td style="text-align:left;"><code>src/screens/admin/AdminCreditPricesScreen.tsx</code></td></tr><tr><td style="text-align:left;"><strong>i18n Locale Bundles</strong></td><td style="text-align:left;">Web: <code>credit.price.{edit,unitCredits,enabled,expectedRevisionConflict}</code> in <code>src/i18n/locales/{vi,en}/credit.json</code>; Mobile: <code>src/i18n/locales/en.json</code> + <code>src/i18n/locales/vi/common.json</code> (<code>tr()</code>)</td></tr></tbody></table><h2 id="_2-database-schema-concurrency-financial-audit-invariants" tabindex="-1">2. Database Schema, Concurrency &amp; Financial/Audit Invariants <a class="header-anchor" href="#_2-database-schema-concurrency-financial-audit-invariants" aria-label="Permalink to &quot;2. Database Schema, Concurrency &amp; Financial/Audit Invariants&quot;">​</a></h2><ol><li><strong>Authoritative Persistence (PostgreSQL <code>ai_credit_operation_prices</code>, <code>audit_logs</code>):</strong><ul><li>Schema objects are defined canonically in <code>database/init/init-postgres-v2.sql</code> and additive migrations under <code>database/migrations/postgres/</code> (plus MongoDB <code>monitoring_*</code> collections for <code>3.10.3</code>).</li><li>Financial and credit amounts use exact integer / <code>BIGINT</code> arithmetic (serialized safely without IEEE-754 float rounding).</li></ul></li><li><strong>Lock Ordering &amp; Optimistic Revisions:</strong><ul><li>Agency-scoped billing and credit mutations acquire parent Agency/Order locks in deterministic order under <code>READ_COMMITTED</code> / <code>REPEATABLE_READ</code> transactions and never hold database transactions open across external HTTP calls (such as SePay API v2 lookups).</li><li>Configuration and broadcast edits enforce <code>expectedRevision</code> / <code>rowVersion</code> optimistic concurrency (<code>409 CONFLICT</code> on stale writes).</li></ul></li></ol><h2 id="_3-end-to-end-execution-flow" tabindex="-1">3. End-to-End Execution Flow <a class="header-anchor" href="#_3-end-to-end-execution-flow" aria-label="Permalink to &quot;3. End-to-End Execution Flow&quot;">​</a></h2><ol><li><strong>Client Action:</strong> Authenticated <code>Admin</code> triggers <code>Update AI Credit Price</code> on <code>pages/credit/prices.tsx</code>, <code>pages/credit/components/CreditPriceDrawer.tsx</code>, <code>CreditAmountForm.tsx</code> or <code>src/screens/admin/AdminCreditPricesScreen.tsx</code>.</li><li><strong>Gateway &amp; Live Role Verification:</strong> API Gateway validates JWT and forwards <code>X-Request-Id</code>; Business service verifies live <code>Admin</code> status and tenant ownership (<code>BR-30, BR-65</code>).</li><li><strong>Transactional Domain Execution:</strong> Service validates invariants, executes atomic persistence on PostgreSQL <code>ai_credit_operation_prices</code>, <code>audit_logs</code>, writes immutable audit trail, and emits outbox/realtime notifications where applicable.</li><li><strong>UI Reconciliation:</strong> Client receives <code>ApiResponse&lt;T&gt;</code> (or streamed <code>application/pdf</code> with <code>Cache-Control: no-store</code>), invalidates scoped <code>(userId, agencyId)</code> <code>TanStack Query</code> caches, and renders localized feedback.</li></ol><h2 id="_4-sequential-build-order" tabindex="-1">4. Sequential Build Order <a class="header-anchor" href="#_4-sequential-build-order" aria-label="Permalink to &quot;4. Sequential Build Order&quot;">​</a></h2><ol><li><strong>Step 1 — Schema &amp; DTO Contracts:</strong> Verify SQL/MongoDB indexes, constraints, and <code>@Valid</code> request/response records.</li><li><strong>Step 2 — Domain Service &amp; Concurrency Guards:</strong> Implement core service logic, lock ordering, idempotency/revision checks, and audit logging.</li><li><strong>Step 3 — REST Controllers &amp; Exception Mapping:</strong> Wire controller endpoints and map domain errors (<code>400/403/404/409/413/503</code>) to <code>ApiResponse</code>.</li><li><strong>Step 4 — Web &amp; Mobile UI Wiring:</strong> Build/connect <code>pages/credit/prices.tsx</code>, <code>pages/credit/components/CreditPriceDrawer.tsx</code>, <code>CreditAmountForm.tsx</code> and <code>src/screens/admin/AdminCreditPricesScreen.tsx</code> with complete Loading, Empty, Success, and Error/Conflict states.</li><li><strong>Step 5 — i18n (<code>vi.json</code> + <code>en.json</code>) &amp; Light/Dark Theme:</strong> Synchronize <code>credit.price.{edit,unitCredits,enabled,expectedRevisionConflict}</code> in <code>src/i18n/locales/{vi,en}/credit.json</code> across <code>vi</code> and <code>en</code> and verify Light/Dark semantic tokens.</li><li><strong>Step 6 — Verification:</strong> Run JUnit 5 + Testcontainers PostgreSQL/MongoDB tests, Jest mobile tests, and Playwright UI tests (<a href="./test.html">test.md</a>).</li></ol><h2 id="_5-localization-vi-json-en-json-theme-tokens-api-envelope-contract" tabindex="-1">5. Localization (<code>vi.json</code> + <code>en.json</code>), Theme Tokens &amp; API Envelope Contract <a class="header-anchor" href="#_5-localization-vi-json-en-json-theme-tokens-api-envelope-contract" aria-label="Permalink to &quot;5. Localization (`vi.json` + `en.json`), Theme Tokens &amp; API Envelope Contract&quot;">​</a></h2><ul><li><strong>Standardized <code>ApiResponse&lt;T&gt;</code> Contract:</strong> All JSON endpoints return <code>{ &quot;success&quot;: boolean, &quot;data&quot;: T, &quot;error&quot;: { &quot;code&quot;, &quot;message&quot; } | null, &quot;requestId&quot;: string }</code> with deterministic HTTP status mapping (<code>200/201/204</code> success; <code>400</code> validation; <code>401</code> unauthenticated; <code>402</code> insufficient credit; <code>403</code> role/tenant forbidden; <code>404</code> scoped not found; <code>409</code> version/idempotency conflict; <code>429</code> rate limit; <code>503</code> upstream unavailable).</li><li><strong>Key-Parallel i18n Synchronization:</strong> All UI strings are added simultaneously in <code>vi.json</code> and <code>en.json</code> on <code>brandhub-web</code> and mirrored via <code>tr()</code> (<code>src/i18n/locales/en.json</code> + <code>src/i18n/locales/vi/common.json</code>) on <code>brandhub-mobile-app</code> — zero hardcoded Vietnamese or English text in JSX/TSX.</li><li><strong>Semantic Light &amp; Dark Mode Styling:</strong> Web components use CSS custom properties and Tailwind <code>dark:</code> variants; Mobile screens use <code>useAppPreferences().palette</code> (<code>src/theme/tokens.ts</code>), maintaining WCAG AA contrast across Light and Dark modes.</li></ul><h2 id="_6-engineering-risks-mitigations" tabindex="-1">6. Engineering Risks &amp; Mitigations <a class="header-anchor" href="#_6-engineering-risks-mitigations" aria-label="Permalink to &quot;6. Engineering Risks &amp; Mitigations&quot;">​</a></h2><ul><li><strong>Cross-User / Cross-Agency Cache Bleed:</strong> Scope all <code>TanStack Query</code> keys by <code>(currentUserId, agencyId, filterParams)</code> and verify ownership server-side on every call.</li><li><strong>Duplicate Webhook / Double-Click Submissions:</strong> Mitigated by <code>Idempotency-Key</code>, unique <code>(provider, merchant_account, event_key)</code> constraints, and disabled busy buttons.</li></ul>',15)])])}const m=t(a,[["render",c]]);export{g as __pageData,m as default};
